import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { formatName } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogHero } from "@/components/ui/dialog";
import { BrandConfirmDialog } from "@/components/ui/BrandConfirmDialog";
import { toast } from "sonner";
import { Gauge, Percent, Plus, Search, Shield, ShieldCheck, Smartphone, Trash2, UserPlus } from "lucide-react";
import { TIER_PERKS, type SubscriptionTier } from "@/lib/subscriptionTiers";
import { AdminViewShell, AdminCard } from "./AdminViewShell";
import type { Database } from "@/integrations/supabase/types";
import { logAdminAction } from "@/lib/adminAudit";
import { unwrapMutation, mutationErrorMessage } from "@/lib/mutationResult";
import { EmptyState } from "@/components/ui/EmptyState";
import { requireBiometric } from "@/lib/biometricGate";
import { resetMinSupportedBuildCache } from "@/lib/minSupportedBuild";
import {
  ABUSE_LIMITS,
  allCapsOff,
  capInputValue,
  describeCap,
  parseCapInput,
  type AbuseLimitKey,
} from "./abuseLimits";

// The fee-ladder rungs an admin is shown, DERIVED from the tier config rather
// than restated. `TIER_PERKS` is the same table `tierFeePercent()` resolves a
// live payout against and the same one /subscription advertises, so the console
// can no longer quote a ladder the platform does not charge — which is exactly
// what the deleted editable inputs did (see the read-only card below).
const FEE_LADDER: { id: SubscriptionTier; name: string; percent: number }[] = (
  ["free", "basic", "pro", "plus", "elite"] as SubscriptionTier[]
).map((id) => ({ id, name: TIER_PERKS[id].name, percent: TIER_PERKS[id].platformFeePercent }));

type Profile = Database["public"]["Tables"]["profiles"]["Row"];

const AdminSettings = () => {
  // Read-only now — displayed as the payout functions' fail-safe fallback, not
  // as an editable rate. See the Fee Model card below for why.
  const [customerFee, setCustomerFee] = useState("");
  const [helperFee, setHelperFee] = useState("");
  const [socialWebhookUrl, setSocialWebhookUrl] = useState("");
  const [savingWebhook, setSavingWebhook] = useState(false);
  const [settingsId, setSettingsId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [minBuild, setMinBuild] = useState<string>("0");
  const [savingMinBuild, setSavingMinBuild] = useState(false);
  // Abuse limits. Held as the raw strings the admin typed so that "blank" is a
  // representable state — a numeric state would have to invent a stand-in for
  // "no limit", and 0 is already spoken for as a synonym of it.
  const [capInputs, setCapInputs] = useState<Record<AbuseLimitKey, string>>(
    () => Object.fromEntries(ABUSE_LIMITS.map((l) => [l.key, ""])) as Record<AbuseLimitKey, string>,
  );
  const [savedCaps, setSavedCaps] = useState<Partial<Record<AbuseLimitKey, number | null>>>({});
  const [savingCaps, setSavingCaps] = useState(false);

  // Admin management
  const [admins, setAdmins] = useState<{ user_id: string; role_id: string; name: string; email: string }[]>([]);
  const [adminsLoading, setAdminsLoading] = useState(true);
  const [showAddDialog, setShowAddDialog] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [searchResults, setSearchResults] = useState<Profile[]>([]);
  const [searching, setSearching] = useState(false);
  const [adding, setAdding] = useState<string | null>(null);
  const [removing, setRemoving] = useState<string | null>(null);
  const [confirmRemove, setConfirmRemove] = useState<{ user_id: string; role_id: string; name: string } | null>(null);

  useEffect(() => {
    loadSettings();
    loadAdmins();
  }, []);

  const loadSettings = async () => {
    const { data, error } = await supabase
      .from("platform_settings")
      .select("*")
      .limit(1)
      .maybeSingle();
    if (error) {
      console.error("[AdminSettings] loadSettings:", error);
      toast.error("Couldn't load platform settings — refresh to retry.");
    } else if (data) {
      const row = data as typeof data & { min_supported_build?: number | null };
      setCustomerFee(String(data.customer_fee_percent ?? 10));
      setHelperFee(String(data.helper_fee_percent ?? 10));
      setSocialWebhookUrl(String(data.social_webhook_url ?? ""));
      setSettingsId(data.id);
      // Defensive defaults — columns are nullable + migration may not
      // be deployed yet, so always normalise to safe values.
      setMinBuild(String(row.min_supported_build ?? 0));
      // Columns added by 20260907230038 and absent until it deploys — read
      // defensively, exactly like min_supported_build above.
      const caps = data as Record<string, unknown>;
      const nextInputs = {} as Record<AbuseLimitKey, string>;
      const nextSaved: Partial<Record<AbuseLimitKey, number | null>> = {};
      for (const limit of ABUSE_LIMITS) {
        const v = caps[limit.key];
        const n = typeof v === "number" ? v : null;
        nextInputs[limit.key] = capInputValue(n);
        nextSaved[limit.key] = n;
      }
      setCapInputs(nextInputs);
      setSavedCaps(nextSaved);
    }
    setLoading(false);
  };

  const saveMinBuild = async () => {
    if (!settingsId) return;
    const n = parseInt(minBuild, 10);
    if (!Number.isFinite(n) || n < 0) {
      toast.error("Min build must be a non-negative integer.");
      return;
    }
    if (n > 999_999) {
      toast.error("Min build must be no greater than 999,999.");
      return;
    }
    setSavingMinBuild(true);
    try {
      unwrapMutation(
        await (supabase.from as any)("platform_settings")
          .update({ min_supported_build: n })
          .eq("id", settingsId)
          .select("id"),
        { action: "update the minimum supported build" },
      );
    } catch (err: any) {
      setSavingMinBuild(false);
      if (err?.code === "42703") {
        toast.error("This setting isn't live yet — the latest database update is still deploying. Try again in a few minutes.");
      } else {
        toast.error(mutationErrorMessage(err, err?.message));
      }
      return;
    }
    setSavingMinBuild(false);
    // Drop this tab's own cached threshold so a second save inside the 60s
    // window is not read back stale. (The gate itself is native-only, so this
    // admin session is never the thing being blocked — this is hygiene, not
    // the mechanism by which the change reaches phones: those re-read on their
    // own TTL and on foreground.)
    resetMinSupportedBuildCache();
    // Say what the save DID, not just that it saved. This control was silent
    // on success while it was inert, which was survivable; now that it turns
    // people away, an operator changing it during an incident needs to see the
    // resulting behaviour confirmed back — and needs "0" to read unmistakably
    // as off, because that is the undo.
    toast.success(
      n === 0
        ? "Force-update gate turned OFF — no device is blocked."
        : `Force-update gate live — native builds below ${n} will be blocked within a minute.`,
    );
    await logAdminAction("update_settings", "platform_settings", settingsId, {
      min_supported_build: n,
    });
  };

  // What the field currently in the box WOULD do, shown live beside it. An
  // unparseable value reads as its own sentence rather than silently previewing
  // "no limit", which would be indistinguishable from a deliberately blank box.
  const capPreview = (key: AbuseLimitKey): string => {
    const parsed = parseCapInput(capInputs[key] ?? "");
    if (!parsed.ok) return parsed.error;
    return describeCap(key, parsed.value);
  };

  const handleSaveCaps = async () => {
    if (!settingsId) return;
    const patch: Record<string, number | null> = {};
    for (const limit of ABUSE_LIMITS) {
      const parsed = parseCapInput(capInputs[limit.key] ?? "");
      if (!parsed.ok) {
        toast.error(`${limit.label}: ${parsed.error}`);
        return;
      }
      patch[limit.key] = parsed.value;
    }
    setSavingCaps(true);
    try {
      unwrapMutation(
        await (supabase.from as any)("platform_settings")
          .update(patch)
          .eq("id", settingsId)
          .select("id"),
        { action: "update the abuse limits" },
      );
    } catch (err: any) {
      setSavingCaps(false);
      if (err?.code === "42703") {
        toast.error("These settings aren't live yet — the latest database update is still deploying. Try again in a few minutes.");
      } else {
        toast.error(mutationErrorMessage(err, err?.message));
      }
      return;
    }
    setSavingCaps(false);
    const nextSaved = patch as Partial<Record<AbuseLimitKey, number | null>>;
    setSavedCaps(nextSaved);
    setCapInputs(
      Object.fromEntries(
        ABUSE_LIMITS.map((l) => [l.key, capInputValue(patch[l.key])]),
      ) as Record<AbuseLimitKey, string>,
    );
    // Read the resulting BEHAVIOUR back, not "saved" — same reasoning as the
    // min-build control: a limit that is now off has removed a protection, and
    // that is the sentence the operator needs to see.
    toast.success(
      ABUSE_LIMITS.map((l) => describeCap(l.key, patch[l.key])).join(" "),
    );
    await logAdminAction("update_settings", "platform_settings", settingsId, patch);
  };

  const handleSaveWebhook = async () => {
    if (!settingsId) return;
    const url = socialWebhookUrl.trim();
    if (url && !/^https?:\/\//i.test(url)) {
      toast.error("Webhook URL must start with http:// or https://");
      return;
    }
    setSavingWebhook(true);
    try {
      unwrapMutation(
        await supabase
          .from("platform_settings")
          .update({ social_webhook_url: url || null })
          .eq("id", settingsId)
          .select("id"),
        { action: "update the social webhook URL" },
      );
    } catch (err: any) {
      setSavingWebhook(false);
      toast.error(mutationErrorMessage(err, err?.message));
      return;
    }
    setSavingWebhook(false);
    await logAdminAction("update_settings", "platform_settings", settingsId, { social_webhook_url: url ? "set" : "cleared" });
  };

  const loadAdmins = async () => {
    setAdminsLoading(true);
    const { data: roles, error: rolesError } = await supabase
      .from("user_roles")
      .select("id, user_id, role")
      .eq("role", "admin");

    if (rolesError) {
      console.error("[AdminSettings] loadAdmins roles:", rolesError);
      toast.error("Couldn't load admin list — refresh to retry.");
      setAdminsLoading(false);
      return;
    }

    if (roles && roles.length > 0) {
      const userIds = roles.map((r) => r.user_id);
      const { data: profiles, error: profilesError } = await supabase
        .from("profiles")
        .select("user_id, full_name, email")
        .in("user_id", userIds);

      if (profilesError) {
        console.error("[AdminSettings] loadAdmins profiles:", profilesError);
      }

      const profileMap = new Map(profiles?.map((p) => [p.user_id, p]) || []);
      setAdmins(
        roles.map((r) => ({
          user_id: r.user_id,
          role_id: r.id,
          name: formatName(profileMap.get(r.user_id)?.full_name, "—"),
          email: profileMap.get(r.user_id)?.email || "—",
        }))
      );
    } else {
      setAdmins([]);
    }
    setAdminsLoading(false);
  };

  const searchUsers = async () => {
    if (!searchQuery.trim()) return;
    setSearching(true);
    const q = searchQuery.trim().toLowerCase();
    const { data, error } = await supabase
      .from("profiles")
      .select("*")
      .or(`full_name.ilike.%${q}%,email.ilike.%${q}%`)
      .limit(10);

    if (error) {
      console.error("[AdminSettings] searchUsers:", error);
      toast.error("Search failed: " + error.message);
      setSearching(false);
      return;
    }

    // Filter out users who are already admins
    const adminIds = new Set(admins.map((a) => a.user_id));
    setSearchResults((data || []).filter((p) => !adminIds.has(p.user_id)));
    setSearching(false);
  };

  const addAdmin = async (profile: Profile) => {
    // Face ID / Touch ID gate: granting admin is the privilege-escalation primitive
    // that makes every other gate on this page moot — an attacker on a
    // merely-unlocked admin phone would grant themselves a durable role that
    // survives the phone being recovered. No-op on web. On device it prompts
    // whenever the device can authenticate its owner at all — falling back to the
    // passcode when biometry is unavailable or locked out (see requireBiometric).
    const ok = await requireBiometric("Confirm granting admin access");
    if (!ok) return;
    setAdding(profile.user_id);
    // The user_roles trigger only admits service_role writes, so the old
    // direct insert here failed on EVERY tap ("Admin roles can only be
    // granted via service_role"). The grant goes through the admin edge
    // function, which verifies the caller and writes the audit log itself —
    // no client-side logAdminAction, or the action would be logged twice.
    const { error } = await supabase.functions.invoke("admin-user-actions", {
      body: { action: "grant_admin", userId: profile.user_id },
    });

    if (error) {
      const detail = await (error as { context?: Response }).context
        ?.clone()
        .json()
        .then((j: { error?: string }) => j?.error)
        .catch(() => undefined);
      toast.error(detail || "Couldn't add the admin — try again.");
    } else {
      await loadAdmins();
      setSearchResults((prev) => prev.filter((p) => p.user_id !== profile.user_id));
    }
    setAdding(null);
  };

  const removeAdmin = async (admin: { user_id: string; role_id: string; name: string }) => {
    // Get current user to prevent self-removal
    const { data: { user } } = await supabase.auth.getUser();
    if (user?.id === admin.user_id) {
      toast.error("You can't remove yourself as admin.");
      return;
    }

    // Face ID / Touch ID gate: stripping admin is the lock-everyone-out half
    // of the same privilege primitive as addAdmin. Runs after the
    // self-removal guard so a blocked action never raises an OS prompt.
    const ok = await requireBiometric("Confirm removing this admin");
    if (!ok) {
      setConfirmRemove(null);
      return;
    }

    setRemoving(admin.role_id);
    try {
      // `.select("id")` because a DELETE that matches zero rows is
      // `{ data: [], error: null }` — indistinguishable from one that stripped
      // the role. This is the lock-everyone-out half of a privilege primitive:
      // an RLS denial or a stale role_id would otherwise have written a
      // "remove_admin" audit entry and reloaded the list over an account that
      // still holds the console.
      unwrapMutation(
        await supabase.from("user_roles").delete().eq("id", admin.role_id).select("id"),
        {
          action: "remove this admin",
          rejectedMessage:
            "That admin role wasn't removed — it may already be gone, or you may not have " +
            "permission. Refresh and check before assuming it's revoked.",
          context: { role_id: admin.role_id },
        },
      );
      await logAdminAction("remove_admin", "user", admin.user_id, { name: admin.name });
      await loadAdmins();
    } catch (err) {
      toast.error(mutationErrorMessage(err, "Couldn't remove the admin — try again."));
    }
    setRemoving(null);
    setConfirmRemove(null);
  };

  if (loading) return <p className="text-muted-foreground">Loading settings…</p>;

  return (
    <AdminViewShell>
      {/* Two columns from `lg` up, one below. Each of the five cards below is a
          short, self-contained control panel, so they were individually capped
          (`max-w-md` / `max-w-lg`) to stop a single form field stretching to
          1128px. Stacked vertically that produced the exact failure CLAUDE.md's
          "every page must FIT THE SCREEN" section names: at 1440 the whole
          Settings screen sat in a ~448px ribbon down the left with ~680px of
          empty page beside it. The cap belongs to the CARD's inner rhythm, not
          to the page, so the caps are gone and the grid does the constraining —
          repeating sibling cards laying out as a grid on wide web is the rule
          the rest of the app already follows. `items-start` keeps a short card
          from stretching to match a tall neighbour. */}
      {/* `[&>*]:min-w-0` is required, not decoration: a grid track defaults to
          `min-width:auto`, so the widest unbreakable child (the fee ladder rows
          and the inline <code> payload string) pushed the single 320px column
          out to 325px and clipped the card inside <main>. Zeroing the track
          minimum lets the cards shrink to the column instead. */}
      <div className="grid items-start gap-5 sm:gap-6 lg:grid-cols-2 [&>*]:min-w-0">
      {/* ── Fee model — READ ONLY ──
          This was two number inputs and a "Total platform take: 20%" calculator
          with a Save button, and every part of it was wrong. The platform has
          not charged one flat rate since the tier ladder shipped: a poster pays
          their own tier's service fee and a Helpr pays their own tier's
          commission, resolved per job by `tierFeePercent()` from the same
          TIER_PERKS table read below. So the console let an admin type a number
          that would never be charged, then added two unrelated percentages
          together and called the sum the platform's take — arithmetic that has
          never described a single real job. Owner: "the 10% payout fee … also
          not correct."

          The platform_settings COLUMNS stay exactly where they are. The payout
          edge functions read customer_fee_percent / helper_fee_percent as a
          fail-safe when a tier cannot be resolved, and release-payout 500s
          without them — so the row is load-bearing infrastructure even though
          it is not a control. It is shown here as what it is: a fallback, with
          its live values, and no way to edit it by accident. */}
      <AdminCard
        title={<span className="flex items-center gap-2"><Percent className="w-4 h-4 text-primary" /> Fee Model</span>}
        subtitle="Set by subscription tier, not by this screen."
        contentClassName="space-y-4"
      >
        {/* The ladder speaks for itself — the paragraph that used to sit above
            it ("each job resolves its own rates from the tier ladder…") said
            what the card's own subtitle already says. */}
        <ul className="rounded-ds-sm bg-primary/5 p-3 space-y-1">
          {FEE_LADDER.map((t) => (
            <li key={t.id} className="flex items-center justify-between text-ds-11">
              <span className="text-muted-foreground">{t.name}</span>
              <span className="font-semibold text-foreground tabular-nums">{t.percent}%</span>
            </li>
          ))}
        </ul>

        {/* Absorbed from the separate "How the split fee model works" card that
            used to sit at the bottom of this screen. Two cards explaining one
            fee model, a page apart, is the duplication itself — not just the
            prose inside them. */}
        <ul className="text-ds-11 text-muted-foreground space-y-1.5 list-disc list-inside">
          <li>Poster pays: job budget + their tier service fee + sales tax, floored at Stripe's cost</li>
          <li>Helpr receives: job budget − their tier commission + urgent bonus</li>
          <li>Platform keeps both — each at that party's own tier rate, so the take differs job to job</li>
        </ul>

        <div className="space-y-1.5 border-t border-border/60 pt-3">
          <p className="text-ds-11 font-semibold text-foreground">Fallback rates</p>
          <p className="text-ds-11 text-muted-foreground">
            Used only when a tier can't be read at payout time. Stored in{" "}
            <code className="text-foreground">platform_settings</code>, where the payout edge functions read them.
          </p>
          <div className="flex flex-wrap gap-x-4 gap-y-1 text-ds-11">
            <span className="text-muted-foreground">
              Poster service fee <span className="font-semibold text-foreground tabular-nums">{customerFee || "—"}%</span>
            </span>
            <span className="text-muted-foreground">
              Helpr commission <span className="font-semibold text-foreground tabular-nums">{helperFee || "—"}%</span>
            </span>
          </div>
        </div>
      </AdminCard>

      {/* Social Webhook URL */}
      <AdminCard
        title="Social Webhook URL"
        subtitle={`Where the Facebook Post Generator's "Send to Social" posts go for scheduling.`}
        contentClassName="space-y-4"
      >
        <div className="space-y-2">
          <Label htmlFor="socialWebhook">Make.com webhook URL</Label>
          <Input
            id="socialWebhook"
            type="url"
            value={socialWebhookUrl}
            onChange={(e) => setSocialWebhookUrl(e.target.value)}
            autoComplete="off"
          />
          <p className="text-ds-11 text-muted-foreground">
            Payload sent: <code className="text-foreground">{`{ post_text, image_url, timing_priority }`}</code>
          </p>
        </div>
        <Button onClick={handleSaveWebhook} disabled={savingWebhook}>
          {savingWebhook ? "Saving…" : "Save Webhook URL"}
        </Button>
      </AdminCard>

      {/* Abuse limits — application caps + the signup throttle */}
      <AdminCard
        title={<span className="flex items-center gap-2"><Gauge className="w-4 h-4 text-primary" /> Abuse Limits</span>}
        subtitle="Blank or 0 means NO LIMIT. All four ship off — turn one on only while you are working an abuse wave, and turn it back off after."
        contentClassName="space-y-4"
      >
        {allCapsOff(savedCaps) && (
          <div className="rounded-ds-md border border-border bg-muted/40 p-3">
            <p className="text-ds-11 text-muted-foreground leading-relaxed">
              All four limits are off, which is the intended default — a Helpr
              can send any number of applications and signups are unthrottled.
              That also means <span className="font-semibold text-foreground">there is no automated abuse protection on either
              path</span>; a script can apply to every open job or hammer signup
              until you set a number here.
            </p>
          </div>
        )}
        <div className="space-y-3">
          {ABUSE_LIMITS.map((limit) => (
            <div key={limit.key} className="space-y-1.5">
              <Label htmlFor={limit.key}>{limit.label}</Label>
              <div className="flex items-center gap-3">
                <Input
                  id={limit.key}
                  type="number"
                  inputMode="numeric"
                  min={0}
                  placeholder="No limit"
                  className="max-w-[9rem]"
                  value={capInputs[limit.key] ?? ""}
                  onChange={(e) =>
                    setCapInputs((prev) => ({ ...prev, [limit.key]: e.target.value }))
                  }
                />
                <span className="text-ds-11 text-muted-foreground">{capPreview(limit.key)}</span>
              </div>
              <p className="text-ds-11 text-muted-foreground leading-tight">{limit.description}</p>
              <p className="text-ds-10 text-muted-foreground font-mono">{limit.key}</p>
            </div>
          ))}
        </div>
        <Button onClick={handleSaveCaps} disabled={savingCaps || !settingsId}>
          {savingCaps ? "Saving…" : "Save Abuse Limits"}
        </Button>
      </AdminCard>

      {/* Min Supported Build */}
      <AdminCard
        title={<span className="flex items-center gap-2"><Smartphone className="w-4 h-4 text-primary" /> Minimum Supported Build</span>}
        subtitle={
          <>
            {/* ENFORCED as of 2026-09-01. This copy said "nothing enforces it
                yet" for as long as that was true, which was the right call —
                an operator would otherwise have set it during an incident and
                believed old builds were being turned away. It is no longer
                true, and a stale reassurance is worse than the original lie:
                it would now talk an operator OUT of using the one lever that
                works while a bad build sits in App Review.

                What reads it: src/hooks/useVersionCheck.ts, via
                get_public_platform_settings() (migration 20260901035235 — the
                table itself is admin-only under RLS, so the column had to
                travel through the RPC to reach a normal user's app).
                src/components/ForceUpdateGate.tsx renders the block.

                The three qualifications below are not hedging, they are the
                actual behaviour, and an operator who does not know them will
                misread what this control did:
                  · NATIVE ONLY. The web app has no build number and updates on
                    reload, so it is never blocked — including /admin, which is
                    where this number gets lowered again.
                  · FAILS OPEN. A failed settings read, an unparseable build, a
                    missing column: all let the user in. A gate that blocks on
                    its own failure is an outage that needs App Review to fix.
                  · Takes about a minute to reach a running app (60s cache),
                    and lands on a backgrounded install when it next comes to
                    the foreground — not only on a cold start. */}
            Blocks native installs older than this build with an{" "}
            <strong className="text-foreground">“Update Helpr to continue”</strong> screen —
            the one lever that works while a bad build is stuck in App Review. Takes
            effect within a minute on running apps.{" "}
            <code className="text-foreground">0</code> is the off value.
            <br />
            <span className="text-ds-11">
              iOS/Android only — the website has no build number and is never blocked.
              The gate fails open, so a settings-read failure never locks anyone out.
              Use the build number from App Store Connect (CFBundleVersion), and set it{" "}
              <em>above</em> the build you are turning away, not equal to it.
            </span>
            <br />
            {/* Not a hypothetical caveat. Probed 2026-09-01: the store URL the
                block screen links to (lib/appStore.ts) returns 404 and the
                iTunes lookup API reports resultCount 0 for its id in four
                storefronts — the listing is not public. Arming the gate today
                would send every blocked user to a dead page, which is why the
                screen also carries the support address. Stated here, next to
                the control, because this is the moment an operator can still
                decide not to. */}
            <span className="text-ds-11 text-[hsl(var(--destructive-ink))]">
              Before setting this above 0, confirm the App Store listing actually
              loads — as of 2026-09-01 the link the block screen sends people to
              returns a 404, which would make the block a dead end. The screen also
              shows the support address, but the store link is the way out.
            </span>
          </>
        }
      >
        <div className="flex items-end gap-2">
          <div className="flex-1 space-y-1.5">
            <Label htmlFor="minBuild">Build code</Label>
            <Input
              id="minBuild"
              type="number"
              min={0}
              max={999_999}
              step={1}
              value={minBuild}
              onChange={(e) => setMinBuild(e.target.value)}
              className="max-w-[160px] font-mono tabular-nums"
            />
          </div>
          <Button onClick={saveMinBuild} disabled={savingMinBuild}>
            {savingMinBuild ? "Saving…" : "Save"}
          </Button>
        </div>
      </AdminCard>

      {/* Admin Management */}
      <AdminCard
        title={<span className="flex items-center gap-2"><ShieldCheck className="w-4 h-4 text-primary" /> Admin Users</span>}
        subtitle={adminsLoading ? undefined : `${admins.length} ${admins.length === 1 ? "account holds" : "accounts hold"} the admin role`}
        action={
          <Button size="sm" onClick={() => { setShowAddDialog(true); setSearchQuery(""); setSearchResults([]); }}>
            <UserPlus className="w-4 h-4 mr-1" /> Add Admin
          </Button>
        }
      >
        {adminsLoading ? (
          <p className="text-ds-11 text-muted-foreground">Loading admins…</p>
        ) : admins.length === 0 ? (
          <EmptyState
            variant="inline"
            icon={Shield}
            title="No admins found"
            body="No accounts currently hold the admin role."
          />
        ) : (
          <div className="space-y-2">
            {admins.map((admin) => (
              <div key={admin.role_id} className="rounded-ds-md liquid-glass p-4 flex items-center justify-between gap-3">
                <div className="min-w-0">
                  <div className="flex items-center gap-2">
                    <p className="font-semibold text-foreground text-ds-13">{admin.name}</p>
                    <Badge className="bg-primary/10 text-primary text-ds-11">Admin</Badge>
                  </div>
                  <p className="text-ds-11 text-muted-foreground mt-0.5">{admin.email}</p>
                </div>
                <Button
                  variant="ghost"
                  size="icon"
                  className="text-destructive hover:bg-destructive/10 shrink-0"
                  disabled={removing === admin.role_id}
                  onClick={() => setConfirmRemove(admin)}
                  aria-label="Remove admin"
                >
                  <Trash2 className="w-4 h-4" />
                </Button>
              </div>
            ))}
          </div>
        )}
      </AdminCard>

      </div>

      {/* The "How the split fee model works" card that used to live here is
          gone — its three bullets moved into the Fee Model card at the top of
          this screen, beside the ladder they describe. Its "Total platform
          take: 20%" row is gone for good: there is no single such number, since
          a job's take is the poster's tier rate plus the Helpr's, independently
          resolved. */}

      {/* Add Admin Dialog */}
      <Dialog open={showAddDialog} onOpenChange={setShowAddDialog}>
        <DialogContent>
          <DialogHero title="Add Admin User" />
          <div className="space-y-4">
            <div className="flex gap-2">
              <Input
                type="search"
                aria-label="Search users by name or email"
                placeholder="Search by name or email…"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && searchUsers()}
              />
              <Button
                onClick={searchUsers}
                disabled={searching}
                size="icon"
                className="shrink-0"
                aria-label="Search users"
              >
                <Search className="w-4 h-4" />
              </Button>
            </div>

            {searching && <p className="text-ds-11 text-muted-foreground">Searching…</p>}

            {searchResults.length > 0 && (
              <div className="space-y-2 max-h-[300px] overflow-y-auto">
                {searchResults.map((profile) => (
                  <div key={profile.id} className="rounded-ds-sm border border-border bg-secondary/20 p-3 flex items-center justify-between gap-3">
                    <div className="min-w-0">
                      <p className="font-medium text-foreground text-ds-13">{formatName(profile.full_name, "—")}</p>
                      <p className="text-ds-11 text-muted-foreground">{profile.email || "—"}</p>
                    </div>
                    <Button
                      size="sm"
                      disabled={adding === profile.user_id}
                      onClick={() => addAdmin(profile)}
                    >
                      {adding === profile.user_id ? "Adding…" : <><Plus className="w-3 h-3 mr-1" /> Add</>}
                    </Button>
                  </div>
                ))}
              </div>
            )}

            {!searching && searchResults.length === 0 && searchQuery.trim() && (
              <p className="text-ds-11 text-muted-foreground text-center py-4">No users found. Try a different search.</p>
            )}
          </div>
        </DialogContent>
      </Dialog>

      <BrandConfirmDialog
        open={!!confirmRemove}
        onOpenChange={(open) => { if (!open) setConfirmRemove(null); }}
        title="Remove This Admin?"
        description={`This revokes admin access for ${confirmRemove?.name || "this user"}. They'll lose access to the admin dashboard immediately.`}
        primaryLabel={confirmRemove && removing === confirmRemove.role_id ? "Removing…" : "Remove Admin"}
        primaryTone="sienna"
        primaryHaptic="error"
        primaryDisabled={!!removing}
        onPrimary={(e) => {
          e.preventDefault();
          if (!confirmRemove) return;
          removeAdmin(confirmRemove);
        }}
        secondaryLabel="Cancel"
      />
    </AdminViewShell>
  );
};

export default AdminSettings;
